def get_max_triples(n):
    a = [i * i - i + 1 for i in range(1, n + 1)]
    count = 0
    mod_map = {}
    for x in a:
        rem = x % 3
        if rem not in mod_map:
            mod_map[rem] = []
        mod_map[rem].append(x)

    # Count triples with sum divisible by 3
    # Possible combinations of remainders (r1, r2, r3):
    # (0,0,0), (1,1,1), (2,2,2), (0,1,2)

    for i in range(len(a)):
        for j in range(i + 1, len(a)):
            for k in range(j + 1, len(a)):
                if (a[i] + a[j] + a[k]) % 3 == 0:
                    count += 1

    return count

